-- NOVA v9.1 staging / de-fa / B1 / Batch 01 / Chapter 01 / Series 081
-- Atomic staging unit. Do not publish or advance production_state from this file alone.
SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;
SET time_zone = '+00:00';
START TRANSACTION;

SET @course_id = (SELECT id FROM courses WHERE course_key='de-fa' LIMIT 1);

VALUES (@course_id,'B1','B1','Gründe, Pläne und Erfahrungen','دلیل ها، برنامه ها و تجربه ها','Zusammenhängender über Gründe, Folgen, Pläne und Erfahrungen sprechen.','درباره دلیل ها، نتیجه ها، برنامه ها و تجربه ها پیوسته تر حرف بزن.',41,60,3,'active')
ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),title=VALUES(title),title_translation=VALUES(title_translation),description=VALUES(description),description_translation=VALUES(description_translation),difficulty_min=VALUES(difficulty_min),difficulty_max=VALUES(difficulty_max),status='active';
SET @level_id=LAST_INSERT_ID();

VALUES (@level_id,'B1-M01','Gründe und Folgen','دلیل و نتیجه','Einfache Gründe nennen und Folgen verständlich ausdrücken.','دلیل های ساده را بگو و نتیجه آنها را روشن بیان کن.',5,41,43,1,'active')
ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),title=VALUES(title),title_translation=VALUES(title_translation),description=VALUES(description),description_translation=VALUES(description_translation),planned_chapter_count=5,difficulty_min=41,difficulty_max=43,status='active';
SET @module_id=LAST_INSERT_ID();

VALUES (@level_id,1,1,8,81,88,'batch_01_chapters_01_08.sql','generating')
ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),status=IF(status='published',status,'generating');
SET @batch_id=LAST_INSERT_ID();

VALUES (@module_id,@batch_id,'B1-M01-C01',81,81,'Warum komme ich später?','چرا دیرتر می رسم؟','Lena und Ben sprechen über eine Zugverspätung. Ben erklärt einen Grund mit weil und eine Folge mit deshalb.','لنا و بن درباره تاخیر قطار حرف می زنند. بن با weil دلیل و با deshalb نتیجه را بیان می کند.',4,41,42,1,'draft',JSON_OBJECT('staging',true,'batch',1,'atomicChapter',1))
ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),batch_id=VALUES(batch_id),title=VALUES(title),title_translation=VALUES(title_translation),description=VALUES(description),description_translation=VALUES(description_translation),planned_lesson_count=4,difficulty_min=41,difficulty_max=42,status='draft',metadata=VALUES(metadata);
SET @chapter_id=LAST_INSERT_ID();

SET @lena_id=(SELECT id FROM characters WHERE course_id=@course_id AND name='Lena' LIMIT 1);
SET @ben_id=(SELECT id FROM characters WHERE course_id=@course_id AND name='Ben' LIMIT 1);

-- New B1 lexical items and explicit phrase targets. Existing canonical words are reused by lemma below.
ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),display_form=VALUES(display_form),translation=VALUES(translation),difficulty=VALUES(difficulty),grammar=VALUES(grammar),distractors=VALUES(distractors),related_words=VALUES(related_words),metadata=VALUES(metadata);

-- LESSON 1
VALUES (@chapter_id,@lena_id,@ben_id,'B1-M01-C01-L01','Eine Verspätung erklären','توضیح دادن یک تاخیر','Einen einfachen Grund mit weil nennen.','با weil یک دلیل ساده بیان کن.','lena-ben-b1-delay-reasons',1,41,240,1,'validated',JSON_OBJECT('staging',true))
ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),status='validated',content_version=content_version+1;
SET @l1=LAST_INSERT_ID();

SELECT @l1,id,ROW_NUMBER() OVER (ORDER BY id),'review',0,1 FROM words WHERE course_id=@course_id AND lemma IN ('Hallo','Ben','wo','sein','du','ich','noch','in','Zug','haben','der','Verspätung','ja','kommen','später','kein','Problem','sagen','bitte','Bescheid')
ON DUPLICATE KEY UPDATE exposure_count=VALUES(exposure_count);
SET @l1t1=(SELECT id FROM turns WHERE lesson_id=@l1 AND sort_order=1); SET @l1t4=(SELECT id FROM turns WHERE lesson_id=@l1 AND sort_order=4); SET @weil=(SELECT id FROM words WHERE course_id=@course_id AND word_key='de-fa-b1-081-weil');

-- LESSON 2
VALUES (@chapter_id,@lena_id,@ben_id,'B1-M01-C01-L02','Nicht pünktlich','سر وقت نمی رسم','Mit weil einen zweiten Grund erklären und pünktlich verwenden.','یک دلیل دیگر را با weil توضیح بده و pünktlich را استفاده کن.','lena-ben-b1-delay-reasons',2,41,240,2,'validated',JSON_OBJECT('staging',true))
ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),status='validated',content_version=content_version+1;
SET @l2=LAST_INSERT_ID();
SET @l2t1=(SELECT id FROM turns WHERE lesson_id=@l2 AND sort_order=1); SET @l2t4=(SELECT id FROM turns WHERE lesson_id=@l2 AND sort_order=4); SET @puenktlich=(SELECT id FROM words WHERE course_id=@course_id AND word_key='de-fa-b1-081-puenktlich');

-- LESSON 3
VALUES (@chapter_id,@lena_id,@ben_id,'B1-M01-C01-L03','Deshalb komme ich später','برای همین دیرتر می رسم','Eine Folge mit deshalb ausdrücken.','با deshalb نتیجه یک اتفاق را بیان کن.','lena-ben-b1-delay-reasons',3,42,240,3,'validated',JSON_OBJECT('staging',true)) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),status='validated',content_version=content_version+1;
SET @l3=LAST_INSERT_ID();
SET @l3t1=(SELECT id FROM turns WHERE lesson_id=@l3 AND sort_order=1); SET @l3t4=(SELECT id FROM turns WHERE lesson_id=@l3 AND sort_order=4); SET @deshalb=(SELECT id FROM words WHERE course_id=@course_id AND word_key='de-fa-b1-081-deshalb');

-- LESSON 4
VALUES (@chapter_id,@lena_id,@ben_id,'B1-M01-C01-L04','Grund und Folge','دلیل و نتیجه','Grund und Folge unterscheiden und kurz ausdrücken.','دلیل و نتیجه را از هم تشخیص بده و کوتاه بیان کن.','lena-ben-b1-delay-reasons',4,42,240,4,'validated',JSON_OBJECT('staging',true)) ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id),status='validated',content_version=content_version+1;
SET @l4=LAST_INSERT_ID();
SET @l4t1=(SELECT id FROM turns WHERE lesson_id=@l4 AND sort_order=1); SET @l4t2=(SELECT id FROM turns WHERE lesson_id=@l4 AND sort_order=2); SET @l4t4=(SELECT id FROM turns WHERE lesson_id=@l4 AND sort_order=4); SET @grund=(SELECT id FROM words WHERE course_id=@course_id AND word_key='de-fa-b1-081-grund'); SET @folge=(SELECT id FROM words WHERE course_id=@course_id AND word_key='de-fa-b1-081-folge');

-- Atomic chapter guardrails. Any failed assertion aborts the transaction by division by zero.
SET @lesson_count=(SELECT COUNT(*) FROM lessons WHERE chapter_id=@chapter_id);
SET @turn_count=(SELECT COUNT(*) FROM turns WHERE lesson_id IN (@l1,@l2,@l3,@l4));
SET @learner_turns=(SELECT COUNT(*) FROM turns WHERE lesson_id IN (@l1,@l2,@l3,@l4) AND role='learner');
SET @learner_targets=(SELECT COUNT(*) FROM turns WHERE lesson_id IN (@l1,@l2,@l3,@l4) AND role='learner' AND speech_target IS NOT NULL AND CHAR_LENGTH(TRIM(speech_target))>0);
SET @reading_count=(SELECT COUNT(*) FROM activities WHERE lesson_id IN (@l1,@l2,@l3,@l4) AND activity_type='reading_comprehension');
SET @character_pair_count=(SELECT COUNT(*) FROM lessons WHERE chapter_id=@chapter_id AND prompt_character_id=@lena_id AND learner_character_id=@ben_id AND prompt_character_id<>learner_character_id);
SELECT IF(@course_id IS NULL OR @lena_id IS NULL OR @ben_id IS NULL,1/0,1) AS dependency_guard;
SELECT IF(@lesson_count<>4 OR @turn_count<>24 OR @learner_turns<>12 OR @learner_targets<>12 OR @reading_count<>4 OR @character_pair_count<>4,1/0,1) AS chapter_guard;

COMMIT;
